#requires -Version 5.1
function Initialize-VisualFixtureAssets {
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][string]$AudioSource)
    # Synthetic identity markers are test content, not replacement production
    # artwork. Campaign records/maps/handouts are generated by the seeders.
    Add-Type -AssemblyName System.Drawing
    $portraits = [ordered]@{
        campaign_bell_beneath_blackwater = @('pc_mira_voss.png','pc_kael_thornevein.png','pc_tamsin_reed.png','pc_elyon_starling.png','pc_nyra_moonbrook.png')
        campaign_clockwork_bloodline = @('pc_iona_vale.png','pc_corvin_rake.png','pc_mirelle_voss.png','pc_tomas_arkwright.png')
    }
    $index = 0
    foreach ($campaign in $portraits.Keys) {
        $directory = Join-Path $Root "Resources/Campaigns/$campaign/Assets/Portraits"
        [IO.Directory]::CreateDirectory($directory) | Out-Null
        foreach ($name in $portraits[$campaign]) {
            $bitmap = New-Object Drawing.Bitmap(64,64)
            try {
                for ($y=0; $y -lt 64; ++$y) {
                    for ($x=0; $x -lt 64; ++$x) {
                        $light = (($x -shr 3) + ($y -shr 3)) % 2
                        $bitmap.SetPixel($x,$y,[Drawing.Color]::FromArgb(255,60+$index*15,80+$light*70,100+$index*9))
                    }
                }
                $bitmap.Save((Join-Path $directory $name),[Drawing.Imaging.ImageFormat]::Png)
            } finally { $bitmap.Dispose() }
            ++$index
        }
    }
    # Reuse the repository's existing audio with its existing rights metadata.
    Copy-Item -LiteralPath $AudioSource -Destination (Join-Path $Root 'Resources/Audio') -Recurse
}
